create table if not exists recordings (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete set null, file_id uuid, storage_url text, duration_seconds int default 0, status text default 'processing', created_at timestamptz default now(), updated_at timestamptz default now()); alter table recordings enable row level security; create index if not exists idx_recordings_room on recordings(room_id);
